// Package path implements gomplate's `path` template-function namespace.
// The functions are thin wrappers over Go's standard `path` package, with
// non-string arguments coerced to strings using fmt's %v semantics, matching
// the reference behaviour.
package path

import (
	"fmt"
	stdpath "path"
)

// NS returns the namespace object whose methods are the `path` template
// functions.
func NS() any {
	return &ns{}
}

type ns struct{}

func toString(in any) string {
	if s, ok := in.(string); ok {
		return s
	}
	return fmt.Sprintf("%v", in)
}

// Base implements path.Base.
func (n *ns) Base(in any) string {
	return stdpath.Base(toString(in))
}

// Clean implements path.Clean.
func (n *ns) Clean(in any) string {
	return stdpath.Clean(toString(in))
}

// Dir implements path.Dir.
func (n *ns) Dir(in any) string {
	return stdpath.Dir(toString(in))
}

// Ext implements path.Ext.
func (n *ns) Ext(in any) string {
	return stdpath.Ext(toString(in))
}

// IsAbs implements path.IsAbs.
func (n *ns) IsAbs(in any) bool {
	return stdpath.IsAbs(toString(in))
}

// Join implements path.Join.
func (n *ns) Join(elem ...any) string {
	s := make([]string, len(elem))
	for i, e := range elem {
		s[i] = toString(e)
	}
	return stdpath.Join(s...)
}

// Match implements path.Match.
func (n *ns) Match(pattern, name any) (bool, error) {
	return stdpath.Match(toString(pattern), toString(name))
}

// Split implements path.Split.
func (n *ns) Split(in any) []string {
	dir, file := stdpath.Split(toString(in))
	return []string{dir, file}
}

package path

import (
	"bytes"
	"testing"
	"text/template"
)

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"path": func() any { return NS() }}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	err = tt.Execute(&buf, map[string]any{"Env": map[string]string{}})
	return buf.String(), err
}

func TestPathFuncs(t *testing.T) {
	tests := []struct {
		name    string
		tmpl    string
		want    string
		wantErr string // substring after "error calling <Name>: "
	}{
		// path.Base
		{"Base simple", `{{ path.Base "/tmp/foo" }}`, "foo", ""},
		{"Base trailing slash", `{{ path.Base "/tmp/foo/" }}`, "foo", ""},
		{"Base empty", `{{ path.Base "" }}`, ".", ""},
		{"Base root", `{{ path.Base "/" }}`, "/", ""},
		{"Base all slashes", `{{ path.Base "///" }}`, "/", ""},
		{"Base pipeline", `{{ "/a/b/c" | path.Base }}`, "c", ""},
		{"Base int coerced", `{{ path.Base 42 }}`, "42", ""},
		{"Base float coerced", `{{ path.Base 1.5 }}`, "1.5", ""},
		{"Base bool coerced", `{{ path.Base true }}`, "true", ""},

		// path.Clean
		{"Clean messy", `{{ path.Clean "/tmp//foo/../" }}`, "/tmp", ""},
		{"Clean empty", `{{ path.Clean "" }}`, ".", ""},
		{"Clean dotdot", `{{ path.Clean "a/../../b" }}`, "../b", ""},
		{"Clean pipeline", `{{ "/x/./y" | path.Clean }}`, "/x/y", ""},
		{"Clean bool coerced", `{{ path.Clean true }}`, "true", ""},

		// path.Dir
		{"Dir simple", `{{ path.Dir "/tmp/foo" }}`, "/tmp", ""},
		{"Dir no slash", `{{ path.Dir "foo" }}`, ".", ""},
		{"Dir root", `{{ path.Dir "/" }}`, "/", ""},
		{"Dir pipeline", `{{ "/a/b" | path.Dir }}`, "/a", ""},

		// path.Ext
		{"Ext simple", `{{ path.Ext "/tmp/foo.csv" }}`, ".csv", ""},
		{"Ext none", `{{ path.Ext "/tmp/foo" }}`, "", ""},
		{"Ext dot in dir only", `{{ path.Ext "/a.b/c" }}`, "", ""},
		{"Ext pipeline", `{{ "x.go" | path.Ext }}`, ".go", ""},
		{"Ext int coerced", `{{ path.Ext 42 }}`, "", ""},

		// path.IsAbs
		{"IsAbs true", `{{ path.IsAbs "/tmp/foo.csv" }}`, "true", ""},
		{"IsAbs false", `{{ path.IsAbs "../foo.csv" }}`, "false", ""},
		{"IsAbs empty", `{{ path.IsAbs "" }}`, "false", ""},
		{"IsAbs int coerced", `{{ path.IsAbs 42 }}`, "false", ""},
		{"IsAbs doc example", `the path is {{ if (path.IsAbs "/tmp/foo.csv") }}absolute{{else}}relative{{end}}`, "the path is absolute", ""},
		{"IsAbs doc example 2", `the path is {{ if (path.IsAbs "../foo.csv") }}absolute{{else}}relative{{end}}`, "the path is relative", ""},

		// path.Join
		{"Join three", `{{ path.Join "/tmp" "foo" "bar" }}`, "/tmp/foo/bar", ""},
		{"Join zero args", `{{ path.Join }}`, "", ""},
		{"Join empty elems", `{{ path.Join "" "" }}`, "", ""},
		{"Join one", `{{ path.Join "a" }}`, "a", ""},
		{"Join cleans", `{{ path.Join "a//b" "../c" }}`, "c", ""},
		{"Join int coerced", `{{ path.Join "/a" 42 "b" }}`, "/a/42/b", ""},

		// path.Match
		{"Match true", `{{ path.Match "*.csv" "foo.csv" }}`, "true", ""},
		{"Match false", `{{ path.Match "*.csv" "foo.txt" }}`, "false", ""},
		{"Match no slash across", `{{ path.Match "*" "a/b" }}`, "false", ""},
		{"Match char class", `{{ path.Match "[a-z]oo" "foo" }}`, "true", ""},
		{"Match int name coerced", `{{ path.Match "*.csv" 42 }}`, "false", ""},
		{"Match bad pattern", `{{ path.Match "[" "x" }}`, "", "syntax error in pattern"},

		// path.Split
		{"Split doc example", `{{ $p := path.Split "/tmp/foo" }}{{ $dir := index $p 0 }}{{ $file := index $p 1 }}dir is {{$dir}}, file is {{$file}}`, "dir is /tmp/, file is foo", ""},
		{"Split no slash", `{{ path.Split "foo" }}`, "[ foo]", ""},
		{"Split dir only", `{{ path.Split "/tmp/" }}`, "[/tmp/ ]", ""},
		{"Split empty", `{{ path.Split "" }}`, "[ ]", ""},
		{"Split int coerced", `{{ path.Split 42 }}`, "[ 42]", ""},

		// argument-count errors surface from text/template itself
		{"Base no args", `{{ path.Base }}`, "", "wrong number of args for Base: want 1 got 0"},
		{"Base two args", `{{ path.Base "a" "b" }}`, "", "wrong number of args for Base: want 1 got 2"},
		{"Match no args", `{{ path.Match }}`, "", "wrong number of args for Match: want 2 got 0"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := render(t, tt.tmpl)
			if tt.wantErr != "" {
				if err == nil {
					t.Fatalf("expected error containing %q, got nil (output %q)", tt.wantErr, got)
				}
				if !bytes.Contains([]byte(err.Error()), []byte(tt.wantErr)) {
					t.Fatalf("error %q does not contain %q", err.Error(), tt.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got != tt.want {
				t.Fatalf("got %q, want %q", got, tt.want)
			}
		})
	}
}

