package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"text/template"

	gpath "gomplate/funcs/path"
)

var tmpls = []string{
	`{{ path.Base "/tmp/foo" }}`,
	`{{ path.Clean "/tmp//foo/../" }}`,
	`{{ path.Dir "/tmp/foo" }}`,
	`{{ path.Ext "/tmp/foo.csv" }}`,
	`the path is {{ if (path.IsAbs "/tmp/foo.csv") }}absolute{{else}}relative{{end}}`,
	`the path is {{ if (path.IsAbs "../foo.csv") }}absolute{{else}}relative{{end}}`,
	`{{ path.Join "/tmp" "foo" "bar" }}`,
	`{{ path.Match "*.csv" "foo.csv" }}`,
	`{{ $p := path.Split "/tmp/foo" }}{{ $dir := index $p 0 }}{{ $file := index $p 1 }}dir is {{$dir}}, file is {{$file}}`,
	`{{ path.Base "" }}`, `{{ path.Base "/" }}`, `{{ path.Base 42 }}`,
	`{{ path.Join }}`, `{{ path.Join "" "" }}`, `{{ path.Join "/a" 42 "b" }}`,
	`{{ path.Split 42 }}`, `{{ path.IsAbs 42 }}`, `{{ path.Clean true }}`,
	`{{ path.Match "[" "x" }}`, `{{ path.Base }}`, `{{ path.Match }}`,
}

func main() {
	fail := 0
	for _, tm := range tmpls {
		tt := template.Must(template.New("<arg>").Funcs(template.FuncMap{"path": func() any { return gpath.NS() }}).Parse(tm))
		var buf bytes.Buffer
		err := tt.Execute(&buf, nil)
		mine := buf.String()
		if err != nil {
			mine = "ERR:" + err.Error()
		}
		cmd := exec.Command("/workspace/executable", "-i", tm)
		out, err2 := cmd.CombinedOutput()
		ref := string(out)
		if err2 != nil {
			ref = "ERR:" + ref
		}
		// for errors, just compare the tail message loosely
		status := "OK"
		if err == nil && err2 == nil {
			if mine != ref {
				status = "MISMATCH"
			}
		} else if (err == nil) != (err2 == nil) {
			status = "MISMATCH(err-status)"
		}
		if status != "OK" {
			fail++
			fmt.Printf("%s tmpl=%q\n mine=%q\n ref =%q\n", status, tm, mine, ref)
		}
	}
	fmt.Println("failures:", fail)
	os.Exit(0)
}
EOF
